-- Instrucciones en espanol (tanda 3), tomadas de instructions.es del dataset.

update public.exercises e
set instructions = v.texto
from (values
  ('extension-de-triceps-en-polea-a-una-mano', 'Ponte de pie frente a una máquina de cable con un accesorio de barra recta a la altura del pecho. Sujeta la barra con un agarre prono y retrocede un paso para crear tensión en el cable. Coloca los pies separados a la altura de los hombros y flexiona ligeramente las rodillas. Mantén la espalda recta y el core activado durante todo el ejercicio. Comienza con el brazo completamente extendido y perpendicular al suelo. Manteniendo la parte superior del brazo inmóvil, exhala y empuja la barra hacia abajo hasta que el brazo quede completamente extendido. Haz una pausa por un momento, luego inhala y regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.'),
  ('press-cerrado-con-barra', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.'),
  ('extension-de-triceps-tumbado-con-barra', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('press-frances', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho. Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos. Haz una pausa breve cuando la barra esté justo encima de la frente y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('extension-de-triceps-sentado-con-barra', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza. Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza. Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('extension-de-triceps-de-pie-con-barra', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.'),
  ('patada-de-triceps', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Acerca los brazos superiores a los costados, con los codos flexionados en un ángulo de 90 grados. Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento. Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('patada-de-triceps-a-una-mano', 'Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados. Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento. Baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('extension-de-triceps-sentado-con-mancuerna', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza. Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas. Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial. Repite el número de repeticiones deseado.'),
  ('extension-de-triceps-de-pie-con-mancuerna', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano. Levanta la mancuerna por encima de la cabeza, manteniendo el brazo recto. Flexiona el codo y baja la mancuerna detrás de la cabeza, manteniendo fija la parte superior del brazo. Extiende el brazo de vuelta hacia arriba, hasta la posición inicial. Repite el número de repeticiones deseado.'),
  ('extension-de-triceps-tumbado-con-mancuernas', 'Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí. Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo. Baja las mancuernas hacia la frente, flexionando los codos. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('press-cerrado-con-mancuernas', 'Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos. Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros. Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial. Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho. Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial. Asegúrate de usar solo los tríceps y no usar los antebrazos ni los bíceps para ayudar a levantar las mancuernas. Después de una pausa de un segundo en la posición contraída, repite el movimiento el número de repeticiones prescrito.'),
  ('press-tate', 'Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí. Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera. Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros. Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado.'),
  ('fondos-de-triceps', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('fondos-en-banco', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.'),
  ('flexiones-diamante', 'Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices. Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos. Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('flexiones-agarre-cerrado', 'Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros. Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados. Empuja con las palmas para extender los brazos y regresar a la posición inicial. Repite el número de repeticiones deseado.'),
  ('press-frances-con-barra-z', 'Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-con-barra', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras comienzas a bajar el cuerpo. Flexiona las rodillas y las caderas, empujando las caderas hacia atrás y hacia abajo como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo o un poco por debajo. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.'),
  ('sentadilla-frontal', 'Empieza de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra frente a los hombros, apoyándola sobre la clavícula y los hombros. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-barra-alta', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Coloca la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras comienzas a bajar en sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, extendiendo las caderas y las rodillas. Repite el número de repeticiones deseado.'),
  ('sentadilla-barra-baja', 'Ponte de pie con los pies separados a la altura de los hombros y la barra apoyada sobre la parte superior de la espalda. Manteniendo el pecho elevado y el core activado, baja lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-stance-cerrado', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas y empujando las caderas hacia atrás. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-stance-ancho', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-hack-con-barra', 'Empieza de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra detrás de las piernas, apoyándola en la parte superior de los muslos. Baja el cuerpo flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-overhead', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos. Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-bulgara-con-barra', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta. Continúa bajando hasta que el muslo delantero quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.'),
  ('sentadilla-goblet', 'Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna verticalmente contra el pecho con ambas manos. Manteniendo el pecho erguido y el core activado, baja el cuerpo a una posición de sentadilla empujando las caderas hacia atrás y flexionando las rodillas. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-bulgara-con-mancuernas', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso hacia adelante con un pie y coloca los pies de modo que el pie delantero quede plano en el suelo y el pie trasero quede elevado sobre un banco o escalón. Baja el cuerpo flexionando la rodilla y la cadera delanteras, manteniendo la rodilla trasera ligeramente flexionada y el talón trasero levantado del suelo. Continúa bajando hasta que el muslo delantero quede paralelo al suelo, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.'),
  ('subida-al-cajon-con-mancuernas', 'Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tus costados. Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté sobre la superficie. Empuja con el talón derecho y sube el cuerpo sobre el escalón, llevando también el pie izquierdo hacia arriba. Una vez que ambos pies estén sobre el escalón, baja el pie izquierdo de vuelta a la posición inicial, manteniendo el pie derecho sobre el escalón. Repite el movimiento, alternando el pie con el que subes cada vez. Continúa durante el número de repeticiones deseado.'),
  ('extension-de-cuadriceps-en-maquina', 'Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la almohadilla para los pies. Sujeta las asas o las barras laterales para mayor estabilidad. Extiende las piernas hacia adelante enderezando las rodillas, levantando el peso. Haz una pausa breve en lo alto, luego baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('prensa-a-una-pierna', 'Ajusta la máquina de trineo a un ángulo de 45 grados. Siéntate en la máquina de trineo con la espalda contra el respaldo y los pies sobre la placa. Coloca un pie sobre la placa y extiende la pierna, empujando el trineo alejándolo de ti. Dobla lentamente la rodilla y baja el trineo de vuelta a la posición inicial. Repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.'),
  ('prensa-en-multipower', 'Ajusta el asiento y la placa para los pies de la máquina Smith a una posición cómoda. Siéntate en la máquina con la espalda apoyada en el respaldo y los pies separados a la altura de los hombros sobre la placa para los pies. Sujeta las asas o los lados de la máquina para mayor estabilidad. Empuja la placa alejándola de ti extendiendo las piernas, manteniendo la espalda contra el respaldo. Haz una pausa por un momento en la posición completamente extendida. Dobla lentamente las rodillas y baja la placa de vuelta hacia ti, regresando a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-en-multipower', 'Configura la máquina Smith con la barra a una altura adecuada para tu sentadilla. Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Colócate debajo de la barra, apoyándola en la parte alta de los trapecios y los hombros. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Activa el core y suelta la barra del soporte, dando un paso atrás para alejarte del soporte. Manteniendo el pecho elevado y la espalda recta, inicia la sentadilla doblando las caderas y las rodillas. Baja el cuerpo hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa por un momento en la posición baja, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-frontal-en-multipower', 'Configura la máquina Smith con la barra a la altura de los hombros. Ponte de pie frente a la barra con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Da un paso atrás y coloca la barra sobre los hombros delanteros, apoyándola en la clavícula y los deltoides. Mantén el pecho elevado, la espalda recta y el core activado. Baja el cuerpo doblando las rodillas y las caderas, como si te sentaras en una silla. Continúa bajando hasta que los muslos queden paralelos al suelo o un poco por debajo. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-sissy', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujétate de un objeto estable para mantener el equilibrio si es necesario. Baja lentamente el cuerpo doblando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido. Continúa bajando hasta que los muslos queden paralelos al suelo o tan lejos como puedas llegar cómodamente. Haz una pausa breve y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('peso-muerto-con-barra', 'Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti. Flexiona las rodillas y las caderas para bajar el torso y agarra la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas. Al ponerte de pie, aprieta los glúteos y mantén el core activado. Baja la barra de vuelta al suelo flexionando las caderas y las rodillas, manteniendo la espalda recta. Repite el número de repeticiones deseado.'),
  ('peso-muerto-sumo', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Coloca una barra en el suelo frente a ti, centrada entre los pies. Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono. Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente. Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos. Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.'),
  ('peso-muerto-rumano', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo. Siente el estiramiento en los isquiotibiales mientras bajas la barra. Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie. Aprieta los glúteos en la parte alta del movimiento. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.'),
  ('peso-muerto-a-una-pierna', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono. Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.'),
  ('rack-pull', 'Coloca una barra en un soporte a la altura de la rodilla. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta. Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas. Repite el número de repeticiones deseado.'),
  ('puente-de-gluteos-con-barra', 'Empieza tumbado boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Coloca una barra sobre las caderas, sujetándola con firmeza con ambas manos. Activa los glúteos y el core, luego levanta las caderas del suelo hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa breve en la parte alta, apretando los glúteos. Baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.'),
  ('zancadas-con-barra', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia delante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al suelo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda, alternando las piernas el número de repeticiones deseado.'),
  ('zancadas-hacia-atras-con-barra', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.'),
  ('zancadas-laterales-con-barra', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de zancada, manteniendo la pierna izquierda recta. Empuja con el pie derecho y vuelve a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo.'),
  ('subida-al-cajon-con-barra', 'Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda. Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla. Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial. Repite con la pierna contraria. Continúa alternando las piernas durante el número de repeticiones deseado.'),
  ('sentadilla-zercher', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('sentadilla-con-salto', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte baja de la sentadilla, impúlsate hacia arriba saltando desde el suelo. Al saltar, extiende las caderas, las rodillas y los tobillos, empujando con la punta de los pies. Aterriza con suavidad de vuelta en la posición de sentadilla y repite el movimiento de inmediato el número de repeticiones deseado.'),
  ('peso-muerto-rumano-con-mancuernas', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono. Manteniendo la espalda recta y el core activado, inclínate desde las caderas y baja las mancuernas hacia el suelo, permitiendo que las rodillas se flexionen ligeramente. Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales, luego empuja con los talones y activa los glúteos para volver a la posición inicial. Repite el número de repeticiones deseado.'),
  ('zancadas-con-mancuernas', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano. Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. Mantén la espalda recta y el pecho erguido mientras bajas el cuerpo. Empuja con el talón derecho para regresar a la posición inicial. Repite con la pierna izquierda. Alterna las piernas el número de repeticiones deseado.')
) as v(ex_slug, texto)
where e.slug = v.ex_slug;
